mapper.update:
UPDATE fin_ex_chat_session_t
SET last_node_order = #{lastNodeOrder},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{sessionId}

UPDATE fin_ex_chat_session_t
SET current_leaf_message_id = #{leafMessageId},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{sessionId}

UPDATE fin_ex_chat_session_t
SET latest_message_seq = GREATEST(latest_message_seq, #{messageSeq})
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{sessionId}

UPDATE fin_ex_chat_session_t
SET last_read_seq = GREATEST(last_read_seq, LEAST(#{readThroughSeq}, latest_message_seq))
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{sessionId}
